import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NumberOnePopProps = Record<string, any>;

const NumberOnePop: React.FC<NumberOnePopProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  primaryColor = "#22c55e", // Green
  innerOutlineColor = "#ffffff", // White
  outerOutlineColor = "#000000", // Black
  fontSize = 350,
  hashScale = 0.65,
  pulseIntensity = 0.03,
  pulseSpeed = 2.5,
  numberText = "1",
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Rubik"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parser safety for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Spring Animation for Pop-in
  const pop = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.8,
    },
    durationInFrames: 30, // Quick pop
  });

  // Continuous Pulse Animation (Sine wave)
  // Starts effectively immediately but scales with the pop
  const pulse = 1 + Math.sin(frame / fps * Math.PI * pulseSpeed) * pulseIntensity;

  // Combine animations
  const scale = pop * pulse;

  // Render Layer Logic
  // We stack 3 identical text layers to create the double-stroke effect
  // Layer 1: Outer Border (Thickest Stroke)
  // Layer 2: Inner Outline (Medium Stroke)
  // Layer 3: Main Text (Fill, No Stroke)
  
  const layers = [
    {
      color: outerOutlineColor,
      strokeWidth: "35px",
      strokeColor: outerOutlineColor,
      zIndex: 1,
    },
    {
      color: innerOutlineColor,
      strokeWidth: "15px",
      strokeColor: innerOutlineColor,
      zIndex: 2,
    },
    {
      color: primaryColor,
      strokeWidth: "0px",
      strokeColor: "transparent",
      zIndex: 3,
    },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${scale})`,
        }}
      >
        {layers.map((layer, index) => (
          <div
            key={index}
            style={{
              position: index === 0 ? "relative" : "absolute", // First layer defines dimension
              top: index === 0 ? undefined : 0,
              left: index === 0 ? undefined : 0,
              width: index === 0 ? undefined : "100%",
              height: index === 0 ? undefined : "100%",
              display: "flex",
              justifyContent: "center",
              alignItems: "baseline",
              zIndex: layer.zIndex,
              fontFamily: "Rubik",
              fontWeight: 900,
              lineHeight: 1,
              // Apply stroke styles
              WebkitTextStroke: `${layer.strokeWidth} ${layer.strokeColor}`,
              color: layer.color,
              // Ensure sharp rendering
              paintOrder: "stroke fill",
              userSelect: "none",
            }}
          >
            <span style={{ fontSize: fontSize * hashScale, marginRight: fontSize * 0.05, transform: "skewX(-12deg)" }}>#</span>
            <span style={{ fontSize: fontSize }}>{numberText}</span>
          </div>
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default NumberOnePop;